document.addEventListener('DOMContentLoaded', function () {
  const form = document.getElementById('quiz-form');
  const score = document.querySelector('[data-testid="quiz-score"]');
  const message = document.getElementById('message');
  const answers = { q1: 'b', q2: 'c', q3: 'b' };

  form.addEventListener('submit', function (event) {
    event.preventDefault();
    const data = new FormData(form);
    const unanswered = ['q1', 'q2', 'q3'].filter(function (name) { return !data.get(name); });
    if (unanswered.length) {
      message.textContent = 'Please choose an answer for every question.';
      return;
    }
    let total = 0;
    Object.keys(answers).forEach(function (name) {
      if (data.get(name) === answers[name]) total += 1;
    });
    score.textContent = String(total);
    score.dataset.score = String(total);
    message.textContent = total === 3 ? 'Perfect score — wonderfully done!' : 'Nice work. You can change your answers and try again.';
  });

  form.addEventListener('change', function () {
    message.textContent = '';
  });
});

document.addEventListener('DOMContentLoaded', function () {
  const form = document.getElementById('quiz-form');
  const score = document.querySelector('[data-testid="quiz-score"]');
  const message = document.getElementById('message');
  const answers = { q1: 'b', q2: 'c', q3: 'b' };
  const questionNames = Object.keys(answers);

  form.addEventListener('submit', function (event) {
    event.preventDefault();
    const selected = questionNames.map(function (name) {
      const input = form.querySelector('input[name="' + name + '"]:checked');
      return input ? input.value : '';
    });
    if (selected.some(function (value) { return value === ''; })) {
      message.textContent = 'Please choose an answer for every question.';
      return;
    }
    const total = questionNames.reduce(function (sum, name, index) {
      return sum + (selected[index] === answers[name] ? 1 : 0);
    }, 0);
    score.textContent = String(total);
    score.dataset.score = String(total);
    message.textContent = total === 3 ? 'Perfect score — wonderfully done!' : 'Nice work. You can change your answers and try again.';
  });

  form.addEventListener('change', function () {
    message.textContent = '';
  });
});

